world_checks.attendees_and_working_hours_exist:
def check(world):
    st = world.state()
    atts = st.get("attendees", [])
    if len(atts) < 4:
        return f"Expected at least 4 attendees with working hours, found {len(atts)}"
    for a in atts:
        if not a.get("email") or not a.get("time_zone") or not a.get("working_hours_start"):
            return f"Attendee record incomplete: {a}"
    return None

world_checks.calendars_have_primary_and_roles:
def check(world):
    st = world.state()
    cals = st.get("calendars", [])
    if len(cals) < 3:
        return f"Expected at least 3 calendars, found {len(cals)}"
    primaries = [c for c in cals if c.get("primary_calendar")]
    if len(primaries) != 1:
        return f"Expected exactly 1 primary calendar, found {len(primaries)}"
    roles = {c.get("access_role") for c in cals}
    if "owner" not in roles or "reader" not in roles:
        return f"Expected owner and reader roles in calendars, got {roles}"
    return None

world_checks.events_and_clock_configured:
def check(world):
    st = world.state()
    clk = st.get("clock", [])
    if not clk or not clk[0].get("now"):
        return "Clock table must have now timestamp"
    cals = st.get("calendars", [])
    if len(cals) < 3:
        return "Calendars table must have baseline calendars"
    return None
